int S_A[MAX_N];
int S_B[MAX_N];

int main(void) {
    int A, B;
    if (scanf("%d %d", &A, &B) != 2) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%d", &S_A[i]);
    }
    for (int i = 0; i < B; i++) {
        scanf("%d", &S_B[i]);
    }

    int ptr_B = 0;
    for (int ptr_A = 0; ptr_A < A && ptr_B < B; ptr_A++) {
        if (S_A[ptr_A] == S_B[ptr_B]) {
            ptr_B++;
        }
    }

    if (ptr_B == B) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
